import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CT6jiXWi.js";const g=JSON.parse('{"title":"Choosing a Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"federation/reference/choosing-a-strategy.md","filePath":"federation/reference/choosing-a-strategy.md","lastUpdated":1783851082000}'),r={name:"federation/reference/choosing-a-strategy.md"};function n(s,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="choosing-a-strategy" tabindex="-1">Choosing a Strategy <a class="header-anchor" href="#choosing-a-strategy" aria-label="Permalink to &quot;Choosing a Strategy&quot;">​</a></h1><p><code>cds-data-federation</code> gives you <strong>two strategies</strong> and, on the delegate strategy, <strong>two optional caching modes</strong>. That is four runtime shapes for the same consumption view:</p><table tabindex="0"><thead><tr><th>#</th><th>Shape</th><th>Annotation</th></tr></thead><tbody><tr><td>1</td><td><strong>Delegate</strong> — live proxy, every read forwarded to the remote</td><td><code>@federation.delegate</code></td></tr><tr><td>2</td><td><strong>Delegate + response cache</strong> — per-query result cached</td><td><code>@federation.delegate: { cache: { strategy: &#39;response&#39; } }</code></td></tr><tr><td>3</td><td><strong>Delegate + entity cache</strong> — full projection snapshot in local SQLite</td><td><code>@federation.delegate: { cache: { strategy: &#39;entity&#39; } }</code></td></tr><tr><td>4</td><td><strong>Replicate</strong> — scheduled sync into a real local table</td><td><code>@federation.replicate</code></td></tr></tbody></table><p>Caching is an <strong>option on delegation</strong>, not a separate strategy: it keeps live-proxy semantics and adds a freshness window. Replication is a genuinely different shape — the data physically lives in your database.</p><p>This page is the decision reference: a quick decision tree, a master comparison matrix, and — because the strategies differ most in what they <em>cannot</em> do — an explicit catalogue of limitations, including OData-protocol limits on delegation.</p><p>For the syntax of every option see <a href="./annotations.html">Annotations</a>; for a per-strategy capability list see <a href="./features.html">Features</a>; for positioning against non-plugin approaches see <a href="./comparison.html">Comparison with CAP</a>.</p><hr><h2 id="quick-decision-tree" tabindex="-1">Quick decision tree <a class="header-anchor" href="#quick-decision-tree" aria-label="Permalink to &quot;Quick decision tree&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Do you need reads to reflect remote writes immediately (strong consistency)?</span></span>
<span class="line"><span>├─ YES ─ must never be stale, or data must not be stored locally</span></span>
<span class="line"><span>│        └─► DELEGATE (no cache)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ MOSTLY ─ live is fine but the remote is slow / rate-limited / costly</span></span>
<span class="line"><span>│        ├─ same queries repeat verbatim ............► DELEGATE + response cache</span></span>
<span class="line"><span>│        └─ arbitrary filters/sorts over one entity .► DELEGATE + entity cache</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ NO ─ staleness is acceptable and you need one of:</span></span>
<span class="line"><span>         • SQL joins to local tables, GROUP BY, $apply, analytics</span></span>
<span class="line"><span>         • offline / remote-outage resilience</span></span>
<span class="line"><span>         • cross-service $expand served from local SQL</span></span>
<span class="line"><span>         └─► REPLICATE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>Rule of thumb: <strong>start with plain delegate.</strong> Add a cache when a concrete latency/load problem appears; move to replicate when you need SQL power, offline resilience, or local joins that delegation cannot express.</p><hr><h2 id="master-comparison-matrix" tabindex="-1">Master comparison matrix <a class="header-anchor" href="#master-comparison-matrix" aria-label="Permalink to &quot;Master comparison matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision signal</th><th>Delegate</th><th>Delegate + response cache</th><th>Delegate + entity cache</th><th>Replicate</th></tr></thead><tbody><tr><td><strong>Freshness</strong></td><td>Always live</td><td>Live within TTL</td><td>Live within TTL</td><td>As of last sync run</td></tr><tr><td><strong>Where data lives</strong></td><td>Remote only</td><td>Cache backend (memory / Redis / …)</td><td>Secondary SQLite (per tenant)</td><td>Your app&#39;s DB table</td></tr><tr><td><strong>First-access cost</strong></td><td>One remote call per request</td><td>One remote call per distinct query</td><td>One remote <strong>full-entity</strong> read per TTL</td><td>One bulk sync per schedule</td></tr><tr><td><strong>Repeat-read cost</strong></td><td>One remote call each time</td><td>Cache hit (identical query)</td><td>Local SQL (any query)</td><td>Local SQL (any query)</td></tr><tr><td><strong>Arbitrary filters/sorts served locally</strong></td><td>—</td><td>Only identical queries</td><td>Yes (any CQN on the entity)</td><td>Yes</td></tr><tr><td><strong>Joins with local tables</strong></td><td>No</td><td>No</td><td>No (separate store)</td><td><strong>Yes</strong></td></tr><tr><td><strong>Aggregation / <code>GROUP BY</code> / <code>$apply</code></strong></td><td><strong>No</strong> (OData limit)</td><td>No</td><td>No</td><td><strong>Yes</strong> (full SQL)</td></tr><tr><td><strong>Offline / remote-outage resilience</strong></td><td>No</td><td>Until TTL (stale)</td><td>Until TTL (stale)</td><td><strong>Full</strong> — table always present</td></tr><tr><td><strong>Reduces remote load</strong></td><td>No</td><td>Yes (per query)</td><td>Yes (one read/TTL)</td><td>Yes (one sync/schedule)</td></tr><tr><td><strong>Write-back (CUD) to remote</strong></td><td>Opt-in, synchronous</td><td>Opt-in (cache not auto-invalidated)</td><td>Opt-in (cache not auto-invalidated)</td><td>Local write only; overwritten by next sync</td></tr><tr><td><strong>Cross-service <code>$expand</code> into this entity served locally</strong></td><td>No (live batch-fetch)</td><td><strong>No</strong> — expand bypasses the cache</td><td><strong>No</strong> — expand falls back to live remote</td><td><strong>Yes</strong> — native SQL join</td></tr><tr><td><strong>Invalidation model</strong></td><td>n/a</td><td>Tags + TTL</td><td>TTL (pipeline reload on miss)</td><td>Schedule / manual run</td></tr><tr><td><strong>Per-tenant isolation</strong></td><td>Remote&#39;s concern</td><td>Auto tenant tag</td><td>One SQLite file per tenant</td><td>CAP MTX per-tenant DB</td></tr><tr><td><strong>Sensitive data kept off local disk</strong></td><td>Yes</td><td>Depends on backend</td><td>No (on local disk)</td><td>No (in local DB)</td></tr><tr><td><strong>Good fit for very large datasets</strong></td><td>Yes</td><td>Yes</td><td>Depends on entity size</td><td>Depends on schema</td></tr><tr><td><strong>Peer dependency</strong></td><td>—</td><td><code>cds-caching</code></td><td><code>cds-data-pipeline</code> (+ <code>@cap-js/sqlite</code>)</td><td><code>cds-data-pipeline</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The two caches never serve a cross-service <code>$expand</code></p><p>When a <strong>local</strong> entity <code>$expand</code>s into a delegated entity (see <a href="./../concepts/cross-service-scenarios.html#cross-service-expand-local--remote">Cross-service expand: local → remote</a>), the plugin batch-fetches the target straight from the remote service. That path does <strong>not</strong> go through the entity&#39;s own READ handler, so neither the response cache nor the entity cache is consulted — every such expand hits the remote. If you need that join to be cheap, use <strong>replicate</strong> (native local SQL join) instead. See <a href="./../integration/caching.html">Caching</a>.</p></div><hr><h2 id="delegate-odata-level-capabilities-and-limits" tabindex="-1">Delegate: OData-level capabilities and limits <a class="header-anchor" href="#delegate-odata-level-capabilities-and-limits" aria-label="Permalink to &quot;Delegate: OData-level capabilities and limits&quot;">​</a></h2><p>Delegation forwards <code>remote.run(req.query)</code> and relies on CAP translating the query through the CDS projection chain. That means a delegated entity is only as capable as the remote <strong>OData</strong> protocol — several CQL/SQL features have no OData equivalent and are rejected.</p><p>Unless noted, the supported items work on <strong>both OData V4 and V2</strong>; several advanced options are <strong>V4 only</strong>.</p><h3 id="supported" tabindex="-1">Supported <a class="header-anchor" href="#supported" aria-label="Permalink to &quot;Supported&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Notes</th></tr></thead><tbody><tr><td>Basic <code>$filter</code> (<code>eq</code>, <code>ne</code>, <code>gt</code>, <code>ge</code>, <code>lt</code>, <code>le</code>, <code>and</code>, <code>or</code>, <code>not</code>)</td><td>CAP-native. V4 + V2.</td></tr><tr><td>String functions <code>contains</code>, <code>startswith</code>, <code>endswith</code>, <code>tolower</code>, <code>toupper</code></td><td>CAP-native. V4 + V2.</td></tr><tr><td><code>$orderby</code>, <code>$select</code>, <code>$top</code>, <code>$skip</code>, <code>$count</code></td><td>Column restriction follows the projection. V4 + V2.</td></tr><tr><td><code>$expand</code> within the <strong>same</strong> remote (<a href="./../concepts/cross-service-scenarios.html#delegated-expand">Delegated expand</a>)</td><td>CAP-native. V4 + V2.</td></tr><tr><td>Nested <code>$expand</code> (<code>$expand=a($expand=b)</code>)</td><td>Recursive rename mapping. V4 + V2.</td></tr><tr><td><code>$filter</code> / <code>$orderby</code> / <code>$top</code> / <code>$skip</code> <strong>inside</strong> <code>$expand</code></td><td><strong>V4 only</strong> (see V2 limitation below).</td></tr><tr><td>Navigation-path <code>$filter</code> through renamed associations (e.g. <code>buyer/name eq &#39;X&#39;</code>)</td><td>Plugin translates the association rename. <strong>V4 only</strong>.</td></tr><tr><td>Lambda operators <code>any</code> / <code>all</code> on to-many</td><td>Plugin workaround. <strong>V4 only</strong>.</td></tr><tr><td><code>$search</code></td><td>CAP forwards it to the remote; searches string columns. <strong>V4</strong>.</td></tr><tr><td>Static <code>where</code> in the consumption view</td><td>Plugin injects the filter into every remote call — a value-add beyond CAP&#39;s native projection support.</td></tr><tr><td>Server-driven paging</td><td>When a remote caps a page below the requested <code>$top</code> (e.g. Northwind&#39;s 20-row default), the handler loops <code>$top</code>/<code>$skip</code> and preserves <code>@odata.count</code>.</td></tr><tr><td>CQL <code>SELECT.one</code>, <code>.columns()</code>, <code>.where()</code>, <code>.orderBy()</code>, <code>.limit()</code>, key shortcut, tagged templates</td><td>Through the application service. Renamed fields resolve correctly.</td></tr><tr><td>Error propagation</td><td>Remote HTTP status, message, and context reach the client.</td></tr></tbody></table><h3 id="not-supported-on-a-delegate-odata-protocol-limits" tabindex="-1">Not supported on a delegate (OData-protocol limits) <a class="header-anchor" href="#not-supported-on-a-delegate-odata-protocol-limits" aria-label="Permalink to &quot;Not supported on a delegate (OData-protocol limits)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Why</th><th>Do this instead</th></tr></thead><tbody><tr><td><strong>Aggregation</strong> — <code>$apply</code>, CQL <code>.groupBy()</code> / <code>.having()</code></td><td>CAP rejects <code>.groupBy</code> for remote services (<em>&quot;Feature not supported: SELECT statement with .groupBy&quot;</em>). OData delegation has no aggregation pushdown.</td><td><strong>Replicate</strong>, then aggregate with local SQL — or use <a href="/cds-data/materialization/"><code>cds-data-materialization</code></a>.</td></tr><tr><td><strong><code>SELECT.distinct</code></strong></td><td>OData has no <code>DISTINCT</code>.</td><td>Replicate + local SQL.</td></tr><tr><td><strong><code>.where()</code> with <code>like</code></strong></td><td>OData has no <code>like</code> keyword.</td><td>Use <code>contains</code> / <code>startswith</code> / <code>endswith</code>.</td></tr><tr><td><strong>Pessimistic locking</strong> — <code>forUpdate()</code> / <code>forShareLock()</code></td><td>Locking is not an OData concept.</td><td>n/a (locking applies to local DB entities only).</td></tr><tr><td><strong>Streaming</strong> — <code>stream()</code> / <code>pipeline()</code> / <code>foreach()</code></td><td>These are <code>DatabaseService</code>-only APIs.</td><td>Replicate, then stream from the local table.</td></tr><tr><td><strong>Flatten associations / path expressions in the projection</strong> (denormalization, e.g. <code>customer.name as buyerName</code>)</td><td>OData cannot denormalize (<em>&quot;OData doesn&#39;t support denormalization&quot;</em>). Works only when the remote is <strong>HCQL</strong> (CAP-to-CAP).</td><td>Use an HCQL provider, or replicate and flatten locally. See <a href="./../concepts/service-query-execution.html#hcql--a-faster-wire-protocol-for-delegate-and-replicate">Service Query Execution → HCQL</a>.</td></tr><tr><td><strong>Cross-service path expressions</strong> (local → remote via association in a projection)</td><td><code>@cds.persistence.skip</code> on the delegate target prevents SQL compilation of the cross-service path.</td><td>Replicate the remote side, then it is an ordinary local path.</td></tr><tr><td><strong>REST protocol delegation</strong></td><td>CAP does not translate CQN to REST; <code>remote.run(req.query)</code> fails against a <code>rest</code> source.</td><td>Use <strong><code>@federation.replicate</code></strong> with a <code>rest</code> source config.</td></tr><tr><td><strong>Renamed fields inside nested-expand <code>$orderby</code></strong> (<code>$expand=orders($orderby=renamedField)</code>)</td><td>The consumer URL parser expects local names; the remote expects remote names; CAP does not translate renames inside nested expand options.</td><td>Order by a non-renamed field, or sort client-side.</td></tr><tr><td><strong>Nested <code>$expand</code> options on OData V2</strong> (<code>$filter</code> / <code>$orderby</code> / <code>$top</code> / <code>$skip</code> inside <code>$expand</code>)</td><td>The V2 adapter silently ignores nested expand options.</td><td>Use V4, or filter/sort after expansion.</td></tr></tbody></table><h3 id="write-back-cud" tabindex="-1">Write-back (CUD) <a class="header-anchor" href="#write-back-cud" aria-label="Permalink to &quot;Write-back (CUD)&quot;">​</a></h3><p>Delegated entities are <strong>read-only by default</strong>. Opt in per entity:</p><table tabindex="0"><thead><tr><th>Annotation</th><th>Effect</th></tr></thead><tbody><tr><td><code>writable: true</code></td><td>Enables <code>CREATE</code> + <code>UPDATE</code> + <code>DELETE</code>.</td></tr><tr><td><code>create</code> / <code>update</code> / <code>delete</code></td><td>Enable one operation; overrides <code>writable</code>.</td></tr><tr><td>(disabled operation)</td><td>Returns <strong>HTTP 405</strong> rather than a DB error.</td></tr></tbody></table><p>CUD forwarding is <strong>synchronous</strong> — the client receives the remote&#39;s response (201/200/204). There is deliberately <strong>no transactional-outbox write-through</strong>: the outbox defers execution and returns no result, which breaks OData&#39;s request/response contract. (The outbox belongs in fire-and-forget scenarios like event notification and cache invalidation.) Note that a successful CUD does <strong>not</strong> auto-invalidate any cache — see below.</p><hr><h2 id="cross-service-expand-and-navigation" tabindex="-1">Cross-service <code>$expand</code> and navigation <a class="header-anchor" href="#cross-service-expand-and-navigation" aria-label="Permalink to &quot;Cross-service \`$expand\` and navigation&quot;">​</a></h2><p>CAP resolves <code>$expand</code> and navigation <strong>within a single service</strong>. When an association crosses the local ↔ remote boundary, the plugin adds resolution. Support is identical whether the remote side is delegate or replicate (the plugin treats any annotated entity as a federation target), but the <em>fetch path</em> differs.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Supported</th><th>Fetch path</th></tr></thead><tbody><tr><td><a href="./../concepts/cross-service-scenarios.html#delegated-expand">Delegated expand</a> (same remote)</td><td>Yes</td><td>CAP-native, forwarded to the remote</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-local--remote">Cross-service expand: local → remote</a></td><td>Yes — incl. to-many, composite keys, nested expand, inner <code>$filter</code>/<code>$orderby</code>/<code>$top</code>/<code>$skip</code>, lambdas</td><td>Batch-fetch from remote + stitch (<strong>bypasses the target&#39;s cache</strong>)</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-cross-provider">Cross-service expand: cross-provider</a></td><td>Yes</td><td>Batch-fetch from each provider + stitch</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-remote--local">Cross-service expand: remote → local</a></td><td>Yes — incl. per-parent <code>$top</code></td><td>Forward remote, query local DB, stitch</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-navigation-local--remote">Cross-service navigation: local → remote</a></td><td>Yes — <code>$select</code> + <code>$filter</code> on target</td><td>Read local FK, delegate to remote</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-navigation-remote--local">Cross-service navigation: remote → local</a></td><td>Yes</td><td>Rewrite to FK-filtered local query</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Extra hop vs. a plain JOIN</p><p>A cross-service expand into a <strong>replicate</strong> entity still runs the batch-fetch/stitch path (the plugin treats it as a federation target), not a single SQL <code>JOIN</code> — correct, but an extra lookup hop. When a target can be a plain <strong>local</strong> (non-annotated) entity, prefer that as the join target for the fastest path.</p></div><hr><h2 id="caching-response-vs-entity-and-their-limits" tabindex="-1">Caching: response vs. entity, and their limits <a class="header-anchor" href="#caching-response-vs-entity-and-their-limits" aria-label="Permalink to &quot;Caching: response vs. entity, and their limits&quot;">​</a></h2><p>Both caches attach to <code>@federation.delegate</code> only. Full option reference: <a href="./annotations.html#cache-option">Annotations → Cache option</a>; mechanics: <a href="./../integration/caching.html">Caching</a>.</p><table tabindex="0"><thead><tr><th></th><th>Response cache (<code>strategy: &#39;response&#39;</code>, default)</th><th>Entity cache (<code>strategy: &#39;entity&#39;</code>)</th></tr></thead><tbody><tr><td>Backend</td><td><code>cds-caching</code> (memory / Redis / HANA / …)</td><td>Secondary SQLite (<code>db</code> or <code>data-federation-cache</code>)</td></tr><tr><td>Cache key</td><td>Full query signature (<code>$filter</code>, <code>$select</code>, <code>$orderby</code>, <code>$top</code>, <code>$skip</code>, <code>$expand</code>)</td><td>The entity — any CQN answered from the snapshot</td></tr><tr><td>Warm-up</td><td>Lazy, per distinct query</td><td>One full remote read per TTL (or <code>preload</code>)</td></tr><tr><td>Invalidation</td><td>TTL + <strong>tag</strong> (<code>federation:&lt;entity&gt;</code>, plus static/dynamic/template tags)</td><td>TTL only (pipeline reload on miss) — no tag invalidation</td></tr><tr><td>Multitenancy</td><td>Auto <code>tenant-…</code> tag (opt out via <code>tenantScoped: false</code>)</td><td>One SQLite file per tenant; <code>static: true</code> for shared reference data</td></tr></tbody></table><h3 id="caching-limitations-both" tabindex="-1">Caching limitations (both) <a class="header-anchor" href="#caching-limitations-both" aria-label="Permalink to &quot;Caching limitations (both)&quot;">​</a></h3><ul><li><strong>Cross-service <code>$expand</code> into the entity is never served from either cache</strong> — it hits the remote (see the tip above).</li><li><strong>No auto-invalidation on CUD.</strong> After a write to a writable delegate, stale entries remain until TTL. Invalidate manually (<code>cache.deleteByTag(&#39;federation:&lt;entity&gt;&#39;)</code> for response) or use a short TTL.</li><li><strong>Missing peer dependency degrades gracefully.</strong> No <code>cds-caching</code> → response caching is skipped with a warning; no <code>cds-data-pipeline</code>/SQLite → entity caching is skipped and live delegation continues.</li></ul><h3 id="entity-cache-—-falls-back-to-the-live-remote-for" tabindex="-1">Entity-cache — falls back to the live remote for <a class="header-anchor" href="#entity-cache-—-falls-back-to-the-live-remote-for" aria-label="Permalink to &quot;Entity-cache — falls back to the live remote for&quot;">​</a></h3><p>The entity cache holds only the <strong>flat projected columns</strong> of the remote entity in one SQLite table, so it forwards to the live remote whenever a query needs more than that table can answer:</p><ul><li>a <strong>static <code>where</code></strong> on the consumption view,</li><li><strong>lambda</strong> (<code>any</code>/<code>all</code>) filters (routed to the direct-remote path),</li><li>a <strong>cross-service (remote → local) <code>$expand</code></strong> on the delegated entity,</li><li>a navigation/lambda filter that was <strong>rewritten to a local-FK <code>IN</code></strong> filter,</li><li><code>$search</code> when <code>search: false</code>,</li><li>any SQLite read/reload <strong>error</strong> (transparent fallback).</li></ul><p>There is deliberately <strong>no scheduled entity-cache refresh</strong> — the always-warm-local-copy use case converges on <code>@federation.replicate</code>; use <code>preload: true</code> / <code>wait: false</code> to avoid a user paying the reload wait.</p><hr><h2 id="replicate-capabilities-and-limits" tabindex="-1">Replicate: capabilities and limits <a class="header-anchor" href="#replicate-capabilities-and-limits" aria-label="Permalink to &quot;Replicate: capabilities and limits&quot;">​</a></h2><p>Replication copies remote data into a real local table on a schedule; reads then run entirely as local SQL.</p><p><strong>Enables:</strong> SQL joins to local tables, <code>GROUP BY</code> / <code>$apply</code> / analytics, offline and remote-outage resilience, cross-service <code>$expand</code> as a native join, streaming, and pessimistic locking — everything delegation&#39;s OData limits forbid. Delta sync supports <strong>timestamp</strong>, <strong>key</strong>, and <strong>datetime-field</strong> modes; writes are idempotent <code>UPSERT</code>; a <code>replicated</code> aspect stamps <code>lastReplicatedAt</code> / <code>lastReplicatedBy</code>.</p><p><strong>Limits:</strong></p><table tabindex="0"><thead><tr><th>Limitation</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Staleness</strong></td><td>Data is only as fresh as the last run. High-churn data that must be exact is a delegate case.</td></tr><tr><td><strong>No write-back</strong></td><td>Replicated tables are read-only mirrors. A local <code>POST</code>/<code>PATCH</code> writes locally, but the next sync treats the remote as source of truth and may overwrite it. Bidirectional sync is not supported.</td></tr><tr><td><strong>Soft-delete propagation</strong></td><td>Source-side deletions are <strong>not</strong> detected/removed today (no tombstone/diff). <em>Not started.</em></td></tr><tr><td><strong>Reconciliation &amp; dry-run</strong></td><td>No periodic drift comparison and no preview-without-write mode. <em>Not started.</em></td></tr><tr><td><strong>Entity ordering</strong></td><td>Parent-before-child ordering for referential integrity is not inferred. <em>Not started.</em></td></tr><tr><td><strong>OData delta tokens</strong></td><td><code>$deltatoken</code> / <code>$deltalink</code> change tracking is not supported; use timestamp/key delta. <em>Not started.</em></td></tr><tr><td><strong>Storage &amp; schedule ops</strong></td><td>You own table growth and must monitor run history — a silently failing job is the most common cause of stale data.</td></tr></tbody></table><hr><h2 id="protocol-support" tabindex="-1">Protocol support <a class="header-anchor" href="#protocol-support" aria-label="Permalink to &quot;Protocol support&quot;">​</a></h2><p>Both strategies work over OData; only replication reaches plain REST.</p><table tabindex="0"><thead><tr><th>Protocol</th><th><code>cds.requires</code> kind</th><th>Delegate</th><th>Replicate</th><th>Notes</th></tr></thead><tbody><tr><td><strong>OData V4</strong></td><td><code>odata</code></td><td>Yes</td><td>Yes</td><td>Default and recommended.</td></tr><tr><td><strong>OData V2</strong></td><td><code>odata-v2</code></td><td>Yes</td><td>Yes</td><td>Needs <code>@cap-js-community/odata-v2-adapter</code>; nested <code>$expand</code> options unsupported; deprecated by SAP — prefer V4.</td></tr><tr><td><strong>HCQL</strong></td><td><code>hcql</code></td><td>Yes</td><td>Yes</td><td>CAP-native; enables flattened path expressions delegation otherwise cannot express.</td></tr><tr><td><strong>REST</strong></td><td><code>rest</code></td><td><strong>No</strong></td><td>Yes</td><td>CAP does not translate CQN to REST. Use replicate with a <code>rest</code> source config.</td></tr></tbody></table><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./features.html">Features</a> — the full per-strategy capability list.</li><li><a href="./annotations.html">Annotations</a> — every option on both annotations and the cache block.</li><li><a href="./../integration/caching.html">Caching</a> — response vs. entity mechanics, storage, and multitenancy.</li><li><a href="./../getting-started/mixing-delegate-and-replicate.html">Mixing delegate and replicate</a> — using both in one service.</li><li><a href="./../concepts/cross-service-scenarios.html">Cross-service scenarios</a> — the canonical <code>$expand</code> / navigation reference.</li><li><a href="./comparison.html">Comparison with CAP</a> — positioning against CAP samples, HANA-native, <code>@cap-js-community/common</code>, and platform tools.</li></ul>`,54)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
